('mission-fruit-2', 'fruit', 'mission', 'Fruit Slash', 'game', 1, array['any','food','healing','social','costa','sports','market']::text[], 'Scout plays Fruit Slash: slicing a fruit reveals its hidden digit. Intel knows which fruits make the vault code. Decoder knows how to scramble it.', '{"scout":{"title":"Fruit Slash","body":"Swipe across flying fruit to slice it. Each fruit type always hides the same digit. Avoid the 💣 (it just costs you time). Call out what you find.","game":{"type":"fruit","fruits":[{"f":"🍇","d":2},{"f":"🍊","d":9},{"f":"🥭","d":3},{"f":"🍍","d":5},{"f":"🍓","d":0},{"f":"🍎","d":4}],"bomb":true,"seconds":30}},"intel":{"title":"Vault order","body":"🍓   🥭   🍎   🍊\n(Strawberry, Mango, Apple, Orange)","big":true},"decoder":{"title":"Scramble rule","body":"Subtract each digit from 9."}}'::jsonb, '[{"label":"4-digit vault code","accept":["9650"]}]'::jsonb, false, 3, 200, 'Scout: shout every fruit and digit you slice. Intel: tell everyone which four fruits matter, in order.', '🍓=0 🥭=3 🍎=4 🍊=9 → 9 minus each digit → 9650', null, 25, 'published'),
